def dissoc(d, *keys):
    """ Return a new dict with the given key(s) removed.

    New dict has d[key] deleted for each supplied key.
    Does not modify the initial dictionary.

    >>> dissoc({'x': 1, 'y': 2}, 'y')
    {'x': 1}
    >>> dissoc({'x': 1, 'y': 2}, 'y', 'x')
    {}
    >>> dissoc({'x': 1}, 'y') # Ignores missing keys
    {'x': 1}
    """
    # Preserve the type of d using its constructor
    try:
        d2 = d.__class__(d)
    except TypeError:
        # fallback for dict subclasses that don't accept an iterable of pairs
        d2 = d.copy()
    # pop with default ignores missing keys, avoiding a conditional test
    for key in keys:
        d2.pop(key, None)
    return d2
